from lib import *
S = SS('x83')
steps = [
    step("用 @Container 加 @ServiceConnection 起一个真实的 MySQL 容器(Testcontainers 2.0.5,镜像 mysql:8.4,Docker 29.8.2),不用写任何 url、用户名配置。从测试类初始化到测试方法开始用了 6874 ms(含启动容器、等它就绪、建 Spring 上下文),整条命令 11959 ms。测试里:容器 id ec4b8a1472dd,JDBC URL 是 jdbc:mysql://localhost:56365/test——端口是随机映射出来的,docker ps 能看到 0.0.0.0:56365->3306/tcp;select version() → 8.4.11。同一份 JdbcTemplate 注入的就是这个容器里的库。测试结束后带 testcontainers 标签的容器一个都不剩。和内存库的差别:存一行 abc,where name = 'ABC' 在 MySQL 里命中 1 行(默认排序规则不区分大小写),在 H2 内存库里命中 0 行;INSERT … ON DUPLICATE KEY UPDATE 在 H2 里报 Syntax error,在 MySQL 里执行成功,v 变成 2。内存库测不出的行为,真实容器能测出来。", t=tl(S(1)), mark=lidx(S(1), 'H2 内存库', 'H2:INSERT', "where name = 'ABC' 命中"), done=lidx(S(1), '从测试类初始化', 'docker ps', 'select version()', 'ON DUPLICATE KEY UPDATE 之后', '测试结束后'), b=bars([['MySQL:where name = ABC 命中的行数', 1, '1'], ['H2:同样 SQL 命中的行数', 0, '0'], ['从类初始化到测试方法开始(ms)', 6874, '6874'], ['整条命令(ms)', 11959, '11959']], 11959, mark=[1], done=[0], cur=[2, 3]), kv=KV([['@ServiceConnection', '不用写 URL、用户名、密码'], ['端口', '每次随机映射,例如 56365'], ['测试结束后', '容器被清掉,docker ps 里没有'], ['内存库 vs 真实 MySQL', '大小写比较、ON DUPLICATE KEY 都不一样']], ['内存库 vs 真实 MySQL'])),
    step("Redis 用 GenericContainer(\"redis:7-alpine\").withExposedPorts(6379) 加 @ServiceConnection(name = \"redis\"):容器 id 7ef4296ea928,容器内 6379 映射到本机 56424;StringRedisTemplate 的 set(带 100 秒过期)和 get 读回 v,getExpire 是 100 秒;整条命令只用了 2472 ms,比起一个 MySQL 容器快得多。测试结束后同样没有残留的容器。注意这里为了不再下载 Ryuk 镜像,我设了 TESTCONTAINERS_RYUK_DISABLED=true,并在每次运行之后自己清理容器;正式使用时 Ryuk 负责在进程异常退出时回收容器。", t=tl(S(2)), mark=lidx(S(2), '[T2] 容器'), done=lidx(S(2), 'set / get', '测试结束后'), b=bars([['Redis 容器整条命令(ms)', 2472, '2472'], ['MySQL 容器整条命令(ms)', 11959, '11959'], ['set 的过期时间(秒)', 100, '100']], 11959, mark=[0], done=[1], cur=[2]), kv=KV([['Redis', '起容器很快,整条命令 2472 ms'], ['@ServiceConnection(name = "redis")', 'GenericContainer 要手动指定名字'], ['映射端口', '6379 → 56424'], ['Ryuk', '本篇关掉了,正式使用请保留']], ['Redis'])),
    step("两个测试类要不要各起一个容器。各自在类里写 static 的 @Container(P1_Own、P2_Own):两个类的容器 id 不同(93d64966ceb3 和 57e1b27d60cc),整条命令 3 次中位 16949 ms(范围 16721 到 16983)。改成把容器放在一个 @TestConfiguration 的 @Bean @ServiceConnection 里,两个测试类都 @Import 它(Q1_Shared、Q2_Shared):两个类拿到同一个容器 id 487bfe748ed3,整条命令中位 7476 ms(范围 7358 到 7597)。共用之所以成立,是因为两个类的 Spring 配置完全一样,命中了上一篇讲的上下文缓存,容器的生命周期跟着上下文走;每个类各起一次,每次都要付出启动 MySQL 的时间。", t=tl(S(3)), mark=lidx(S(3), '各自 @Container(static 字段):'), done=lidx(S(3), '共用 @TestConfiguration 里的', '对比'), b=bars([['各自 @Container 的整条命令中位(ms)', 16949, '16949'], ['共用 @Bean 容器的整条命令中位(ms)', 7476, '7476'], ['各自 @Container 创建的容器个数', 2, '2'], ['共用 @Bean 创建的容器个数', 1, '1']], 16949, mark=[0, 2], done=[1, 3]), kv=KV([['每个类各一个 @Container', '2 个容器,16949 ms'], ['@Bean + @ServiceConnection + @Import', '1 个容器,7476 ms'], ['能共用的前提', 'Spring 上下文配置完全相同(上下文缓存命中)'], ['容器生命周期', '跟着缓存的上下文走']], ['@Bean + @ServiceConnection + @Import'])),
]
